CREATE SCHEMA identity;
CREATE SCHEMA merchant;
CREATE SCHEMA payment;
CREATE SCHEMA paymentmethod;
CREATE SCHEMA account;
CREATE SCHEMA refund;
CREATE SCHEMA transaction;
CREATE SCHEMA notification;
CREATE SCHEMA analytics;
CREATE TABLE identity.users (id varchar PRIMARY KEY, name varchar NOT NULL, email varchar NOT NULL, role varchar NOT NULL);
CREATE TABLE merchant.merchants (id varchar PRIMARY KEY, user_id varchar NOT NULL, name varchar NOT NULL, status varchar NOT NULL);
CREATE TABLE payment.payments (id varchar PRIMARY KEY, client_id varchar NOT NULL, merchant_id varchar NOT NULL, payment_method_id varchar NOT NULL, amount numeric(15,2) NOT NULL, currency varchar NOT NULL, status varchar NOT NULL, description varchar, created_at varchar NOT NULL);
CREATE TABLE paymentmethod.payment_methods (id varchar PRIMARY KEY, client_id varchar NOT NULL, type varchar NOT NULL, last_four varchar NOT NULL, status varchar NOT NULL);
CREATE TABLE account.accounts (id varchar PRIMARY KEY, owner_id varchar NOT NULL, balance numeric(15,2) NOT NULL, currency varchar NOT NULL, status varchar NOT NULL);
CREATE TABLE refund.refunds (id varchar PRIMARY KEY, payment_id varchar NOT NULL, amount numeric(15,2) NOT NULL, currency varchar NOT NULL, status varchar NOT NULL, created_at varchar NOT NULL);
CREATE TABLE transaction.transactions (id varchar PRIMARY KEY, payment_id varchar NOT NULL, client_id varchar NOT NULL, amount numeric(15,2) NOT NULL, currency varchar NOT NULL, type varchar NOT NULL, created_at varchar NOT NULL);
CREATE TABLE notification.notifications (id varchar PRIMARY KEY, recipient_id varchar NOT NULL, message varchar NOT NULL, status varchar NOT NULL, created_at varchar NOT NULL);
CREATE TABLE analytics.payment_statistics (id varchar PRIMARY KEY, merchant_id varchar NOT NULL, period_from varchar NOT NULL, period_to varchar NOT NULL, payment_count int NOT NULL, total_amount numeric(15,2) NOT NULL, refund_amount numeric(15,2) NOT NULL, revenue numeric(15,2) NOT NULL);
